package com.procurement.quotationcomparison.entity;import com.procurement.rfq.entity.Rfq;import jakarta.persistence.*;import lombok.*;import java.time.*;@Entity@Table(name="quotation_comparisons",uniqueConstraints={@UniqueConstraint(columnNames="comparison_number"),@UniqueConstraint(columnNames="rfq_id")})@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builder public class QuotationComparison{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="quotation_comparison_id")private Long id;@Column(name="comparison_number",nullable=false,length=40)private String comparisonNumber;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="rfq_id",nullable=false)private Rfq rfq;@Enumerated(EnumType.STRING)@Column(name="comparison_method",nullable=false,length=20)private ComparisonMethod comparisonMethod;@Column(name="comparison_date",nullable=false)private LocalDate comparisonDate;@Column(name="prepared_by",nullable=false,length=100)private String preparedBy;@Column(name="approved_by",length=100)private String approvedBy;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private ComparisonStatus status;@Column(length=1000)private String remarks;@Column(name="created_by",nullable=false)private String createdBy;@Column(name="updated_by")private String updatedBy;@Column(name="created_at",updatable=false)private LocalDateTime createdAt;@Column(name="updated_at")private LocalDateTime updatedAt;@PrePersist void pre(){var n=LocalDateTime.now();createdAt=n;updatedAt=n;if(status==null)status=ComparisonStatus.DRAFT;}@PreUpdate void upd(){updatedAt=LocalDateTime.now();}}
